CREATE TABLE "config"."curated_mapping" ("id" bigint NOT NULL GENERATED ALWAYS AS IDENTITY, "from_framework_code" text NOT NULL, "from_version_label" text NOT NULL, "from_citation_norm" text NOT NULL, "to_framework_code" text NOT NULL, "to_version_label" text NULL, "to_citation_norm" text NOT NULL, "relationship" text NOT NULL DEFAULT 'related', "mapping_source_code" text NOT NULL DEFAULT 'operator', "note" text NOT NULL DEFAULT '', "origin" text NOT NULL DEFAULT 'seed', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "uq_config_curated_mapping" UNIQUE NULLS NOT DISTINCT ("from_framework_code", "from_version_label", "from_citation_norm", "to_framework_code", "to_version_label", "to_citation_norm", "mapping_source_code"), CONSTRAINT "chk_config_curated_mapping_origin" CHECK (origin = ANY (ARRAY['seed'::text, 'user'::text])), CONSTRAINT "chk_config_curated_mapping_rel" CHECK (relationship = ANY (ARRAY['equivalent'::text, 'subset-of'::text, 'superset-of'::text, 'intersects'::text, 'related'::text, 'incorporated-into'::text, 'moved-to'::text])));
